const fixed = (setup: AwsConnectionSetup): AwsRoleSetupClient => ({ setup: async () => setup });

const connectionId = readOnly.subject.replace("connection:", "");
const progressId = "7d1f2a3b-4c5d-4e6f-8a9b-0c1d2e3f4a5b";
const recently = () => new Date(Date.now() - 20_000).toISOString();
/** The agent's checklist at one moment; the setup step reads it as if the agent had just sent it. */
function progressAt(status: AgentSetupProgress["status"], items: AgentSetupProgressItem[], summary: string | null = null): AgentSetupProgressClient {
  const progress: AgentSetupProgress = {
    id: progressId, companyId: "company-storybook", purpose: "aws_connection", subjectId: connectionId, status, items, summary,
    expiresAt: new Date(Date.now() + 6 * 3600_000).toISOString(), createdAt: recently(), updatedAt: recently(),
  };
  const base = `https://acme.paperclip.app/api/agent-setup-progress/${progressId}`;
  return {
    create: async () => ({ progress, token: "pcsp_storybook", urls: { checklist: `${base}/checklist`, item: `${base}/items/{key}`, finish: `${base}/finish` } }),
    get: async () => progress,
  };
}
const step = (key: string, title: string, status: AgentSetupProgressItem["status"], detail: string | null = null): AgentSetupProgressItem => ({ key, title, status, detail });
const roleArn = `arn:aws:iam::123456789012:role/${readOnly.roleName}`;

const meta = {
  id: "connection-setup-aws-role",
  title: "Apps, channels, and extensions/Connection setup/Apps/Connections/AWS role",
  component: AwsRoleSetup,
  parameters: { layout: "padded", paperclip: { implementation: "production", boundary: "fixtures",
    capabilities: ["connection-setup/credentials", "connection-setup/failure"],
    notes: "Production AWS role setup step with a template generated by the server for a synthetic connection. No AWS call is made." } },
  decorators: [(Story) => <div className="mx-auto max-w-xl"><Story /></div>],
  args: { connectionId, client: fixed(readOnly), onBack: () => {}, onTest: () => {} },
} satisfies Meta<typeof AwsRoleSetup>;

export default meta;
type Story = StoryObj<typeof meta>;

export const ReadOnly: Story = {};
export const FullAccess: Story = { args: { client: fixed({ ...readOnly, accessLevel: "full" }) } };
export const TestFailed: Story = { args: { error: "AWS refused this connection's role. Check that the role exists and trusts this connection." } };
export const AddressChanged: Story = { args: { client: fixed({ available: false, reason: "address_changed" }) } };
export const RoleArnSaved: Story = { args: { client: fixed({ ...readOnly, savedRoleArn: "arn:aws:iam::123456789012:role/" + readOnly.roleName }) } };
export const NotReachable: Story = { args: { client: fixed({ available: false, reason: "loopback" }) } };

// Each live-progress story uses its own account, so the checklist one story saves in the session is never picked up by another.
/** With live progress: the agent has not reported yet. */
export const AgentWaiting: Story = { args: { companyId: "company-storybook", progressAccountId: "storybook-waiting", progressClient: progressAt("waiting", []) } };
/** The agent set its checklist and is part way through. */
